import { expect, expectStatus, test, uniqueName, type APIRequestContext } from "../../fixtures";

const API_URL = process.env.API_URL ?? "http://localhost:8000";

// Polls a document until extraction finishes. Assumes the document status moves from
// "processing" to "extracted" and the extraction endpoint then returns the record.
async function waitForExtraction(api: APIRequestContext, documentId: string) {
  for (let attempt = 0; attempt < 60; attempt++) {
    const doc = await api.get(`/api/documents/${documentId}`);
    if (doc.ok()) {
      const body = (await doc.json()) as { status: string };
      if (body.status === "extracted") {
        const extraction = await api.get(`/api/documents/${documentId}/extraction`);
        return (await expectStatus<{ id: string; status: string }>(extraction, 200));
      }
      if (body.status === "failed") {
        throw new Error(`Extraction failed for document ${documentId}`);
      }
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`Timed out waiting for extraction of document ${documentId}`);
}

test.describe("review vendors", () => {
  test(
    "an expired insurance certificate cannot be approved",
    { tag: "@REV-07" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Expired Cert Vendor"),
          category: "services",
          contact_email: `expired-${suffix}@vendors.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(vendorResponse, 201);

      // The insurance certificate fixture is named so the seeded extractor reads an
      // expiry date of yesterday (2026-11-10) from it.
      const kinds = ["w9", "insurance_certificate", "contract"] as const;
      const extractions: Record<string, { id: string; status: string }> = {};
      for (const kind of kinds) {
        const filename = kind === "insurance_certificate" ? `expired-insurance-${suffix}.pdf` : `${kind}-${suffix}.pdf`;
        const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: filename,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 ${kind} ${suffix}`),
            },
          },
        });
        const document = await expectStatus<{ id: string }>(upload, 201);
        extractions[kind] = await waitForExtraction(member, document.id);
      }

      // Submit the vendor now that all three documents are extracted.
      const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
      await expectStatus(submit, 200);

      const insuranceExtractionId = extractions.insurance_certificate.id;

      // Act: a reviewer tries to approve the expired insurance certificate extraction.
      const decision = await reviewer.post(`/api/extractions/${insuranceExtractionId}/decision`, {
        data: { decision: "approve" },
      });

      // Assert: the approval is refused with the expired-insurance error code.
      const body = await expectStatus<{ error: { code: string } }>(decision, 409);
      expect(body.error.code).toBe("insurance_expired");
    },
  );
});
